-- Phase 1M additive progress valuation layer. Existing ipc_submissions/payment workflow remains unchanged.
begin;
create table if not exists boq_contract_rates (id text primary key default gen_random_uuid()::text,organization_id text not null references organizations(id) on delete cascade,project_id text not null references projects(id) on delete cascade,activity_id text not null references activities(id) on delete cascade,unit_rate numeric(15,2) not null check(unit_rate>=0),effective_from date not null,status text not null default 'active' check(status in ('active','superseded')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(activity_id,effective_from));
create table if not exists ipc_valuation_periods (id text primary key default gen_random_uuid()::text,organization_id text not null references organizations(id) on delete cascade,project_id text not null references projects(id) on delete cascade,reference_number text not null,period_start date not null,period_end date not null,status text not null default 'draft' check(status in ('draft','submitted','review','certified','rejected')),created_by uuid references auth.users(id) on delete set null,submitted_by uuid references auth.users(id) on delete set null,reviewed_by uuid references auth.users(id) on delete set null,certified_by uuid references auth.users(id) on delete set null,certified_at timestamptz,rejection_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,reference_number),check(period_end>=period_start));
create table if not exists ipc_valuation_lines (id text primary key default gen_random_uuid()::text,organization_id text not null references organizations(id) on delete cascade,valuation_period_id text not null references ipc_valuation_periods(id) on delete cascade,activity_id text not null references activities(id) on delete restrict,rate_id text references boq_contract_rates(id) on delete set null,planned_quantity numeric(14,3) not null,previous_certified_quantity numeric(14,3) not null,current_quantity numeric(14,3) not null,cumulative_quantity numeric(14,3) not null,unit_rate numeric(15,2) not null,current_value numeric(15,2) not null,cumulative_value numeric(15,2) not null,exceeds_boq boolean not null default false,snapshot jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(valuation_period_id,activity_id));
create table if not exists ipc_valuation_measurement_links (id text primary key default gen_random_uuid()::text,organization_id text not null references organizations(id) on delete cascade,valuation_period_id text not null references ipc_valuation_periods(id) on delete cascade,measurement_id text not null references boq_item_measurements(id) on delete restrict,activity_id text not null references activities(id) on delete restrict,created_at timestamptz not null default now(),unique(valuation_period_id,measurement_id));
alter table boq_item_measurements add column if not exists certified_valuation_period_id text references ipc_valuation_periods(id) on delete set null;
create unique index if not exists boq_measurement_one_certified_valuation on boq_item_measurements(id) where certified_valuation_period_id is not null;
create index if not exists idx_boq_contract_rates_activity on boq_contract_rates(organization_id,project_id,activity_id,effective_from desc) where status='active';
create index if not exists idx_ipc_valuation_period_project on ipc_valuation_periods(organization_id,project_id,status,period_start);
create index if not exists idx_ipc_valuation_links_measurement on ipc_valuation_measurement_links(organization_id,measurement_id);
create or replace function private.phase1m_guard_ipc_child() returns trigger language plpgsql security definer set search_path=public,auth as $$ begin
 if tg_table_name='boq_contract_rates' and not exists(select 1 from activities a where a.id=new.activity_id and a.project_id=new.project_id) then raise exception 'Rate activity must belong to project' using errcode='42501'; end if;
 if tg_table_name='ipc_valuation_lines' and not exists(select 1 from ipc_valuation_periods p where p.id=new.valuation_period_id and p.organization_id=new.organization_id) then raise exception 'IPC line must belong to organization' using errcode='42501'; end if;
 if tg_table_name='ipc_valuation_measurement_links' and not exists(select 1 from boq_item_measurements m join ipc_valuation_periods p on p.id=new.valuation_period_id where m.id=new.measurement_id and m.activity_id=new.activity_id and m.organization_id=new.organization_id and p.organization_id=new.organization_id and m.status='approved') then raise exception 'IPC measurement link must reference approved same-tenant measurement' using errcode='42501'; end if;
 return new;end $$;
drop trigger if exists phase1m_rate_guard on boq_contract_rates;create trigger phase1m_rate_guard before insert or update on boq_contract_rates for each row execute function private.phase1m_guard_ipc_child();
drop trigger if exists phase1m_line_guard on ipc_valuation_lines;create trigger phase1m_line_guard before insert or update on ipc_valuation_lines for each row execute function private.phase1m_guard_ipc_child();
drop trigger if exists phase1m_link_guard on ipc_valuation_measurement_links;create trigger phase1m_link_guard before insert or update on ipc_valuation_measurement_links for each row execute function private.phase1m_guard_ipc_child();
alter table boq_contract_rates enable row level security;alter table ipc_valuation_periods enable row level security;alter table ipc_valuation_lines enable row level security;alter table ipc_valuation_measurement_links enable row level security;
comment on table ipc_valuation_periods is 'Phase 1M progress valuation/certification. It is not an IPC payment record.';
commit;
